def aligned_tree(net, pos, root="any"):
    """沿 BFS 生成树做**平行移动积分**，得到全局坐标（确定性、`O(E)`、无迭代）。

    规则（纯 id + 环序）：BFS 从 root 出发；处理边 i→w 时
      g = M_i · dir_i(w)                              （i 的全局标架下的 i→w 方向）
      p_w = p_i + (r_i + r_w)·g                       （树边精确满足相切目标长）
      M_w = R(u→−g)，其中 u = dir_w(i)                （把 w 标架的「指向 i」转到 −g）

    返回 {"pos", "frames", "tree_edges", "holonomy"}：
      holonomy[(i,w)] = 用 i 的标架预测 w 的位置与树位置之差（非树边）。
      该量**非零是几何事实**（离散曲率无法在平面容纳），不是误差 —— 见模块 docstring。
    """
    ids = net.ids()
    if not ids:
        return {"pos": {}, "frames": {}, "tree_edges": [], "holonomy": {}}
    if root == "any":
        root = random.choice(ids)
    tree = bfs_tree(net, root)
    st = stack([root])
    frames = {v: Frame() for v in ids}
    pos = {v: tuple(pos[v]) for v in ids}
    tree_edges = []
    holonomy = {}
    while st:
        i = st.pop()
        for w in net.rot[i]:
            if w in frames and w not in tree_edges:
                tree_edges.append((i, w))
                g = frames[i].dir_to(w)
                d = (net.rad[w] + net.rad[i]) * g
                pos[w] = tuple(v + d for v, d in zip(pos[i], d))
                frames[w] = Frame(rot=frames[w].rot,
                                  dirs={u: (-g if u == w else d)
                                        for u, d in frames[w].dirs.items()},
                                  pos=pos[w])
    for e in net.edges():
        if e not in tree_edges:
            (i, w) = sorted(e)
            h = tuple(pos[w][k] - (pos[i][k] +
                                   (net.rad[w] + net.rad[i]) *
                                   frames[i].dir_to(w)[k])
                       for k in range(3))
            holonomy[e] = h
    return {"pos": pos, "frames": frames, "tree_edges": tree_edges,
            "holonomy": holonomy}

def sigma_global(net):
    """GT-008 全局 σ = |V| / |E| = 2 / ⟨deg⟩。"""
    ids = net.ids()
    m = len(ids)
    if not m:
        return 0.0
    sum_deg = sum(net.deg(v) for v in ids)
    return 2.0 * m / sum_deg if sum_deg else float("inf")

def edge_set(net):
    """无向边集合（id 对，规范化 (min,max)）。"""
    return {(v, w) if v < w else (w, v)
            for e in net.edges() for v, w in (e.ids(),)}

def snap(net):
    """帧快照（深拷贝旋转系统，保留 id 计数器）——L3 以 id 对齐，故必须冻结每帧。"""
    return RotNet({v: tuple(r) for v, r in net.rot.items()},
                   ids=net.ids(), cap=net.cap())

def _edge_set(rows):
    """无向边集合（规范化 (min,max)，确定性排序）。"""
    ids = {(r["v"], r["w"]) for r in rows}
    return sorted((min(a, b), max(a, b)) for a, b in ids)

def intersection(net, pos, cap=6):
    """§3.5 交集提交判据：候选存活 ⟺ 它的每个角点都接受它。

    按候选汇总被接受的入射数，与角点数相等即存活。
    """
    seen = Counter()
    for v in net.ids():
        seen[v] += sum(1 for w in net.rot[v] if pos[w][2] >= 0)
    return {v for v in seen if seen[v] == cap}

def degree_next(net, corner_nodes=None, break_u=None, break_v=None):
    """§4.3 修剪标记：先算下一帧度数，再标出 deg < dmin 的位置。

    deg_{t+1}(v) = deg_t(v) + (以 v 为角点的锥化次数) − (v 的入射断边数)。
    corner_nodes / break_u / break_v 均为**位置下标**。
    """
    ids = net.ids()
    m_prev = len(net.edges())
    deg = {v: net.deg(v) for v in ids}
    pos = {v: net.pos(v) for v in ids}
    nb = _next_breaks(net, corner_nodes, break_u, break_v)
    for u in sorted(nb["break_u"] | nb["break_v"]):
        if u in deg:
            deg[u] -= 1
    for c in nb["corners"]:
        deg[c] += 1
    return {"ids": ids, "m_prev": m_prev, "m_next": len(net.edges()),
            "delta_m": len(net.edges()) - m_prev,
            "deg": deg, "pos": pos, "n_deleted": nb["deleted"],
            "n_created": nb["created"], "n_total": nb["total"],
            "break_u": nb["break_u"], "break_v": nb["break_v"],
            "corner_nodes": nb["corner_nodes"]}
